import React, { useEffect, useRef, useState } from 'react';
import { Text, View, Pressable, StyleSheet } from 'react-native';
import { tokens } from '../theme';
interface Reading { sensorId: string; value: number; unit: string; }
interface MeasurementCardProps { reading: Reading; onRefresh: () => void; }
const HIGHLIGHT_THRESHOLD = 38;
const styles = StyleSheet.create({ card: { padding: tokens.spacing.medium }, warning: { backgroundColor: tokens.colors.warningSurface } });
export function MeasurementCard({ reading, onRefresh }: MeasurementCardProps) {
  const [seconds, setSeconds] = useState(0);
  const timer = useRef<ReturnType<typeof setInterval> | undefined>(undefined);
  useEffect(() => {
    timer.current = setInterval(() => setSeconds(value => value + 1), 1000);
    return () => { if (timer.current !== undefined) clearInterval(timer.current); };
  }, []);
  const highlighted = reading.value >= HIGHLIGHT_THRESHOLD;
  return <View style={[styles.card, highlighted && styles.warning]}><Text>{reading.value}{reading.unit} · {seconds}s</Text><Pressable accessibilityRole="button" accessibilityLabel="刷新读数" onPress={onRefresh}><Text>刷新</Text></Pressable></View>;
}

fixtures.task.md:
使用给定技能处理以下普通 TypeScript 工程任务。只输出可评审的关键代码、必要注释和验证安排，不修改或运行工程，不调用其他代理。

需求：整理 `read.ts` 和 `failure.ts` 的职责、条件与类型，保留现有返回字段及反馈。另有一个新详情读取入口，它调用同一 HTTP 客户端并返回相同原始信封，请说明如何接入这份公共读取能力。

现有约定：
- `code: 200` 表示成功，数据可能缺失或为 false、0，必须原样保留；其他整数码为业务拒绝。
- 取消和调用归属失效返回 cancelled，旧结果不得用于新调用。有效调用发生程序异常时返回 failed/service，并记录安全错误类型及阶段。
- 调用者拥有 AbortController、Promise 和监听清理，取消事件会立即调用 finish(cancelled)。finish 可重复调用但只第一次生效，完成时同步释放监听再 resolve；已交付成功不被稍后的取消改写。不要改变这一完成时机。
- 网络错误详细日志由 http 接入层维护，HTTP 客户端拒绝时可能带 code。`authorize`、`current`、`decode` 都可能抛错；仅允许处理既定的失败返回，不增加重试、超时、缓存或业务写入。
- Catalog 和 Detail 两个调用方都只使用本模块公开结果。公共读取没有更多消费者，项目不要求新增框架或统一重排目录。

read.ts（类型以 failure.ts 为准）：
```ts
export function read(ctx: Context, path: string, finish: (result: Result) => void) {
  let phase = 'authorization';
  (async () => {
    const auth = await ctx.authorize();
    if (ctx.signal.aborted || !ctx.current()) {
      finish({ status: 'cancelled' });
      return;
    }
    if (!auth) {
      finish({ status: 'failed', reason: 'access' });
      return;
    }
    phase = 'request';
    let response;
    try {
      response = await ctx.http.get(path, auth, ctx.signal);
    } catch (error) {
      if (ctx.signal.aborted || !ctx.current()) {
        finish({ status: 'cancelled' });
        return;
      }
      const code = ctx.http.errorCode(error);
      finish({ status: 'failed', reason: 'service', ...(code === 'ETIMEDOUT' ? { serviceReason: 'timeout' } : code === 'ERR_NETWORK' ? { serviceReason: 'network' } : {}) });
      return;
    }
    phase = 'response';
    if (ctx.signal.aborted || !ctx.current()) {
      finish({ status: 'cancelled' });
      return;
    }
    finish(ctx.decode(response));
  })().catch(error => {
    ctx.recordFailure(error, phase);
    finish({ status: 'failed', reason: 'service' });
  });
}
```

failure.ts：
```ts
export interface Failure {
  status: 'failed';
  reason: 'access' | 'service' | 'rejected';
  accessReason?: 'session' | 'forbidden';
  serviceReason?: 'network' | 'timeout' | 'unknown';
  message?: string;
}
export function failureReason(result: Failure) {
  return result.reason === 'access' ? result.accessReason ?? 'session' : result.reason === 'service' ? result.serviceReason ?? 'unknown' : result.reason;
}
export function failureMessage(result: Failure) {
  const reason = result.reason === 'access' ? result.accessReason ?? 'session' : result.reason === 'service' ? result.serviceReason ?? 'unknown' : result.reason;
  return result.message ?? messages[reason];
}
```

`Result` 另含 `{status:'success', data?:unknown}` 和 `{status:'cancelled'}`。Context 中的 http、recordFailure 与 decode 已有实现和公开类型；使用其已有接口，不复制实现。recordFailure 已保证不会抛错并过滤敏感字段。messages 是已有固定文案表；Failure.message 的空字符串也要原样保留。

